using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;

namespace ByteBitReverse;

public class BitReverser
{
    // Scalar lookup table: LUT[b] == bit-reversed b.
    private static readonly byte[] Lut = BuildLut();

    private static byte[] BuildLut()
    {
        var lut = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int r = 0;
            int v = i;
            for (int bit = 0; bit < 8; bit++)
            {
                r = (r << 1) | (v & 1);
                v >>= 1;
            }
            lut[i] = (byte)r;
        }
        return lut;
    }

    // Nibble-reverse LUT used by SIMD shuffle: index by low nibble → reversed
    // bits placed in the high nibble position, and vice-versa.
    private static ReadOnlySpan<byte> NibbleReverse =>
    [
        0x00, 0x08, 0x04, 0x0C,
        0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D,
        0x03, 0x0B, 0x07, 0x0F
    ];

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static void ReverseInPlace(Span<byte> data)
    {
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int length = data.Length;
        int i = 0;

        if (Avx2.IsSupported && length >= 32)
        {
            var nibbleLut = Vector256.Create(NibbleReverse);
            var lowMask = Vector256.Create((byte)0x0F);

            for (; i + 32 <= length; i += 32)
            {
                var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);

                // Split into nibbles, look up each reversed nibble, recombine swapped.
                var lo = vec & lowMask;
                var hi = Vector256.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & lowMask;

                var revLo = Avx2.Shuffle(nibbleLut, lo);
                var revHi = Avx2.Shuffle(nibbleLut, hi);

                var result = Vector256.ShiftLeft(revLo.AsInt16(), 4).AsByte() | revHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }

        if (Ssse3.IsSupported && i + 16 <= length)
        {
            var nibbleLut = Vector128.Create(NibbleReverse);
            var lowMask = Vector128.Create((byte)0x0F);

            for (; i + 16 <= length; i += 16)
            {
                var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);

                var lo = vec & lowMask;
                var hi = Vector128.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & lowMask;

                var revLo = Ssse3.Shuffle(nibbleLut, lo);
                var revHi = Ssse3.Shuffle(nibbleLut, hi);

                var result = Vector128.ShiftLeft(revLo.AsInt16(), 4).AsByte() | revHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }

        // Scalar tail via LUT.
        ref byte lutRef = ref MemoryMarshal.GetArrayDataReference(Lut);
        for (; i < length; i++)
        {
            ref byte b = ref Unsafe.Add(ref ptr, i);
            b = Unsafe.Add(ref lutRef, b);
        }
    }
}

